// The "latest daily current-affairs PDF" band on the home page, from the downloads data the PDF script maintains
// (src/data/downloads.mjs, newest first). One data object feeds both the React home page and the prerender, so
// they cannot disagree. It names the real edition date: editions are generated by hand, so the band never says
// "today's" for a PDF that may be a day or two old.
import { DAILY_PDF_EDITIONS } from '../data/downloads.mjs';
import { formatHubDate } from './examHub.mjs';

const LANGUAGE = { en: 'English', hi: 'Hindi' };

export function dailyPdfBand() {
  const latest = DAILY_PDF_EDITIONS[0];
  if (!latest) return null;
  const meta = [
    formatHubDate(latest.date, 'en'),
    `${LANGUAGE[latest.language] ?? latest.language} edition`,
    `${latest.pages} pages`,
    `${latest.sizeKb} KB`,
  ].join(' · ');
  return {
    eyebrow: 'Daily PDF',
    title: 'Daily current-affairs PDF',
    body: `Latest edition: ${meta}. Every item links to its official source, and each edition ends with ${latest.questions} practice questions.`,
    buttonLabel: 'Download the PDF',
    file: latest.file,
    allLabel: 'All daily editions and monthly capsules',
    allHref: '/downloads/',
    date: latest.date,
  };
}
